  ('f582c5ef-2077-5f6f-b889-8f22db371cd5', null, (select id from public.skills where slug = 'integers-rational-numbers'), null, 'medium',
   $q$Which list shows $-1.2$, $\frac{1}{4}$, $-\frac{3}{2}$ and $0$ in order from greatest to least?$q$, $q$[{"text":"$-\\frac{3}{2}$, $-1.2$, $\\frac{1}{4}$, $0$","is_correct":false,"misconception_token":"ordered-by-absolute-value"},{"text":"$-\\frac{3}{2}$, $-1.2$, $0$, $\\frac{1}{4}$","is_correct":false,"misconception_token":"listed-least-to-greatest"},{"text":"$\\frac{1}{4}$, $0$, $-\\frac{3}{2}$, $-1.2$","is_correct":false,"misconception_token":"ordered-negatives-by-absolute-value"},{"text":"$\\frac{1}{4}$, $0$, $-1.2$, $-\\frac{3}{2}$","is_correct":true}]$q$::jsonb, $q$$\frac{1}{4}$, $0$, $-1.2$, $-\frac{3}{2}$$q$, $q$Write $-\frac{3}{2}$ as $-1.5$. The only positive number, $\frac{1}{4}$, is greatest, then $0$. Between the negatives, $-1.2$ is closer to $0$ than $-1.5$, so $-1.2$ is greater. The order is $\frac{1}{4}$, $0$, $-1.2$, $-\frac{3}{2}$. The list that puts $-\frac{3}{2}$ before $-1.2$ treats the bigger distance from $0$ as the bigger number.$q$, 'draft', null)
